package recordingpipeline

import (
	"strings"
	"testing"
	"time"

	"github.com/q9labs/chalk/apps/api/internal/utilities"
)

// Generated by master on 2026-09-30 with only random authority handles replaced.
const masterV1CaptureEnvelope = `{"schema_version":"recorder_job.v2","tenant_id":"40000000-0000-4000-8000-000000000002","space_id":"40000000-0000-4000-8000-000000000005","episode_id":"40000000-0000-4000-8000-000000000003","recording_id":"40000000-0000-4000-8000-000000000004","job_id":"40000000-0000-4000-8000-000000000001","kind":"capture","attempt_count":1,"fencing_generation":2,"capture_epoch":1,"policy_snapshot_version":"episode_config.v2","hard_deadline":"2026-09-30T10:00:00Z","capture_ready_at":null,"initial_plan_revision":1,"bundle_schema_version":"recording_bundle.v1","layout_profile":"composite_720p_v1","participant_limit":10,"input_bitrate_bps":4000000,"audio_codec":"opus","video_codecs":["vp8","h264"],"plan_handle":"<plan>","signaling_handle":"<signaling>","key_handle":"<key>","object_handle":"<object>"}`

func TestDefaultCaptureEnvelopeBytesMatchMaster(t *testing.T) {
	id := func(value string) utilities.ID {
		parsed, err := utilities.ParseID(value)
		if err != nil {
			t.Fatal(err)
		}
		return parsed
	}
	now := time.Date(2026, 9, 30, 9, 0, 0, 0, time.UTC)
	job := Job{ID: id("40000000-0000-4000-8000-000000000001"), TenantID: id("40000000-0000-4000-8000-000000000002"), EpisodeID: id("40000000-0000-4000-8000-000000000003"), RecordingID: id("40000000-0000-4000-8000-000000000004"), Kind: JobKindCapture, AttemptCount: 1, FencingGeneration: 2}
	facts := ClaimFacts{SpaceID: id("40000000-0000-4000-8000-000000000005"), PolicySnapshotVersion: SupportedPolicySnapshotVersion, HardDeadline: now.Add(time.Hour), CaptureEpoch: 1}
	claimID := id("40000000-0000-4000-8000-000000000006")
	authority, err := NewRecorderJobAuthority(job, facts, claimID, now)
	if err != nil {
		t.Fatal(err)
	}
	normalized := string(authority.EnvelopeBytes)
	for _, pair := range [][2]string{{authority.Envelope.PlanHandle, "<plan>"}, {authority.Envelope.SignalingHandle, "<signaling>"}, {authority.Envelope.KeyHandle, "<key>"}, {authority.Envelope.ObjectHandle, "<object>"}} {
		normalized = strings.ReplaceAll(normalized, pair[0], pair[1])
	}
	if normalized != masterV1CaptureEnvelope {
		t.Fatalf("default envelope bytes differ from master:\n got %s\nwant %s", normalized, masterV1CaptureEnvelope)
	}
	facts.BundleSchemaVersion = RecordingBundleSchema
	v2, err := NewRecorderJobAuthority(job, facts, claimID, now)
	if err != nil {
		t.Fatal(err)
	}
	if v2.Envelope.BundleSchemaVersion != RecordingBundleSchema {
		t.Fatalf("enabled capture schema = %q", v2.Envelope.BundleSchemaVersion)
	}
	job.Kind = JobKindRender
	ready := now.Add(-time.Minute)
	facts.CaptureReadyAt = &ready
	facts.CaptureKeyHandle = id("40000000-0000-4000-8000-000000000007")
	facts.PresentationHandle = id("40000000-0000-4000-8000-000000000008")
	facts.PresentationSchemaVersion = "recording_presentation.v1"
	facts.PresentationProfileVersion = "composite_720p_v1"
	facts.PresentationSHA256 = make([]byte, 32)
	facts.PresentationDurationMillis = 60_000
	render, err := NewRecorderJobAuthority(job, facts, claimID, now)
	if err != nil {
		t.Fatal(err)
	}
	if render.Envelope.BundleSchemaVersion != LegacyRecordingBundleSchema {
		t.Fatalf("render schema under v2 flag = %q", render.Envelope.BundleSchemaVersion)
	}
	job.Kind = JobKindTranscription
	transcription, err := NewRecorderJobAuthority(job, facts, claimID, now)
	if err != nil {
		t.Fatal(err)
	}
	if transcription.Envelope.BundleSchemaVersion != LegacyRecordingBundleSchema {
		t.Fatalf("transcription schema under v2 flag = %q", transcription.Envelope.BundleSchemaVersion)
	}
}
